def generar_ruta_algoritmica(ruta_base, desvios, probabilidad=0.5):
    """
    Algoritmo que evalúa los nodos y decide si desviarse o seguir la principal.
    """
    ruta_final = []
    i = 0
    while i < len(ruta_base):
        punto_actual = ruta_base[i]
        desvio_encontrado = False
        
        # Evaluar si el punto actual es el inicio de algún desvío evaluado (20 desviaciones)
        for clave, puntos_desvio in desvios.items():
            # Si el punto actual coincide con el inicio de un desvío y el azar lo decide
            if punto_actual == puntos_desvio[0] and random.random() < probabilidad:
                # Insertamos el camino alterno
                ruta_final.extend(puntos_desvio)
                
                # Buscamos dónde se reincorpora este desvío en la ruta principal
                punto_reincorporacion = puntos_desvio[-1]
                for j in range(i, len(ruta_base)):
                    if ruta_base[j] == punto_reincorporacion:
                        i = j # Saltamos los puntos de la principal que "nos saltamos"
                        desvio_encontrado = True
                        break
            if desvio_encontrado: break
            
        if not desvio_encontrado:
            ruta_final.append(punto_actual)
            i += 1
            
    return ruta_final

# 3. GENERACIÓN DE LAS 3 RUTAS REQUERIDAS
ruta_1 = generar_ruta_algoritmica(ruta_principal, nodos_desvio, probabilidad=0.3)
ruta_2 = generar_ruta_algoritmica(ruta_principal, nodos_desvio, probabilidad=0.6)
